// ===== island : 悬空主岛 + 云岛 =====
mf.group('island',()=>{
  for(let y=0;y<9;y++){
    const k=(y+1)/9, hx=Math.round(14+38*k*k), hz=Math.round(8+26*k*k);
    B(-hx,y,-hz,hx*2+1,1,hz*2+1,ST);
  }
  B(-52,9,-34,105,1,69,SO);
  B(-52,10,-34,105,1,69,G);
  B(-52,10,-34,105,1,1,ST); B(-52,10,34,105,1,1,ST);
  B(-52,10,-34,1,1,69,ST);  B(52,10,-34,1,1,69,ST);
  B(-46,11,24,6,2,5,ST); B(40,11,-30,5,2,4,ST); B(30,11,22,4,1,4,ST);
  const isles=[[30,72,-46,11],[78,98,18,9],[-66,86,-46,8]];
  for(const [cx,cy,cz,r] of isles){
    for(let y=0;y<5;y++){const k=1-y/5,hx=Math.round(r*k),hz=Math.round(r*0.75*k);
      if(hx>0&&hz>0) B(cx-hx,cy-y,cz-hz,hx*2+1,1,hz*2+1,ST);}
    const wx=Math.round(r*1.25),wz=Math.round(r*0.95);
    B(cx-wx,cy+1,cz-wz,wx*2+1,2,wz*2+1,CL);
    B(cx-4,cy+3,cz-3,9,2,7,CL);
    B(cx-2,cy+5,cz-1,5,2,4,CL);
    B(cx-3,cy+3,cz-2,6,1,4,G);
    B(cx+3,cy+4,cz+2,1,4,1,WD); B(cx+1,cy+8,cz,5,3,5,LV);
    B(cx-6,cy+3,cz+4,1,2,1,LA);
