});

// ===== building : 主建筑体量 + 拱形入口 + 蓝色分层屋顶 =====
mf.group('building',()=>{
  const x0=-30,z0=-20,w=41,d=33;
  B(x0,11,z0,w,2,d,CO);
  const wy=13,wh=30;
  B(x0,wy,z0,w,wh,3,ST);
  B(x0,wy,z0+d-3,w,wh,3,ST);
  B(x0,wy,z0,3,wh,d,ST);
  B(x0+w-3,wy,z0,3,wh,d,ST);
