  // 檐口 + 蓝色分层屋顶
  B(-32,42,-22,45,1,38,CU);
  for(let i=0;i<=7;i++) B(-31+i,43+2*i,-20+2*i,42-2*i,2,32-4*i,BL);
  // 烟囱
  B(2,45,-14,4,12,4,ST); B(1,57,-15,6,2,6,CU);
});

