  mf.paint([cx-6,cy,15],[1,1,1],{style:GD}); mf.paint([cx+6,cy,15],[1,1,1],{style:GD});
  mf.paint([cx,cy,15],[1,1,1],{style:GD});
  // 塔顶
  for(let i=0;i<=5;i++) B(tx+i,66+2*i,tz+i,tw-2*i,2,td-2*i,BL);
  B(-40,78,5,4,6,4,CU); B(-38,84,7,1,5,1,GD); B(-40,86,7,3,1,1,GD);
  mf.paint([-40,83,7],[4,1,1],{style:GD});
});

// ===== bridge : 带拱形负空间的连接桥 =====
mf.group('bridge',()=>{
  const z0=-6,d=13;
  B(50,10,z0,33,1,d,CU);
  B(50,11,z0,33,1,d,WD);
